// Register the DynamicQuery-vocabulary enums that are PERSISTED as entity fields (Signum ships these as
// real int-backed enums with their own table, e.g. UserQueryEntity.columnsMode / UserQueryEntity_Order.orderType).
// Registering an enum here only makes it resolvable as an enum type; a table is created lazily by the
// schema builder only when a FieldEnum actually references it (so registering the unused ones is harmless).
//
// altea divergence: the query layer uses the string-union TYPE alias (`OrderType`) at runtime, so the enum
// OBJECT must keep the `Enum` suffix (`OrderTypeEnum`) — the registered clean name / table name therefore
// carries that suffix (Signum's "OrderType" → altea "OrderTypeEnum"). The runtime/wire value stays the member
// NAME string (EnumSerializer), so query/FindOptions code is unaffected; only the DB column becomes an int FK
// to the enum table (translatable), and the in-memory field value is the numeric ordinal (like OrderState) —
// callers that need the string name normalise with `Enum.toName`. The registerEnum() calls below are rewritten
// by the quote-transformer to `registerEnum(X, "X", __fileInfo)`.
registerEnum(ColumnOptionsMode);
registerEnum(CombineRows);
registerEnum(DashboardBehaviour);
registerEnum(FilterGroupOperation);
registerEnum(FilterOperation);
registerEnum(OrderType);
registerEnum(PaginationMode);
registerEnum(PinnedFilterActive);
registerEnum(RefreshMode);
registerEnum(SystemTimeJoinMode);
registerEnum(SystemTimeMode);
registerEnum(TimeSeriesUnit);

// These twelve are Signum's `Signum.DynamicQuery` namespace, which the core assembly maps to the
// `queries` SCHEMA (`[assembly: AssemblySchemaName("queries", ForNamespace = "Signum.DynamicQuery")]`).
// altea groups its core model by role rather than by target schema, so they sit in this file beside the
// `basics` types that @altea/altea/data declares — hence the per-type override, one per line so adding
// or moving one is a single-line diff. See setDatabaseSchema.
setDatabaseSchema("queries",
    ColumnOptionsMode,
    CombineRows,
    DashboardBehaviour,
    FilterGroupOperation,
    FilterOperation,
    OrderType,
    PaginationMode,
    PinnedFilterActive,
    RefreshMode,
    SystemTimeJoinMode,
    SystemTimeMode,
    TimeSeriesUnit,
);
